import{_ as o,o as r,c as a,ai as e}from"./chunks/framework.BBSijY9B.js";const p=JSON.parse('{"title":"什么是 Grok Bot","description":"用一句话、一张对照表和几个场景，讲清 Grok Bot 和普通聊天 AI 的区别。","frontmatter":{"related":["/start/create-first-bot","/start/brief-tasks-clearly","/basics/cloud-computer"],"title":"什么是 Grok Bot","description":"用一句话、一张对照表和几个场景，讲清 Grok Bot 和普通聊天 AI 的区别。","section":"start","order":1,"tags":["入门","概念","云电脑"],"sources":["https://x.ai/news/introducing-grok-bot","https://docs.x.ai/grok-bot/overview","https://cursor.com/docs/grok-bot/work"],"wordCount":794,"readingTime":2,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"什么是 Grok Bot | WANGXXXL"}],["meta",{"property":"og:description","content":"用一句话、一张对照表和几个场景，讲清 Grok Bot 和普通聊天 AI 的区别。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/start/what-is-grok-bot"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/start-what-is-grok-bot-dbb62b6178.png"}],["meta",{"property":"og:image:alt","content":"什么是 Grok Bot · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"什么是 Grok Bot | WANGXXXL"}],["meta",{"name":"twitter:description","content":"用一句话、一张对照表和几个场景，讲清 Grok Bot 和普通聊天 AI 的区别。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/start-what-is-grok-bot-dbb62b6178.png"}],["meta",{"name":"twitter:image:alt","content":"什么是 Grok Bot · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/start/what-is-grok-bot"}]]},"headers":[],"relativePath":"start/what-is-grok-bot.md","filePath":"start/what-is-grok-bot.md","lastUpdated":1792485206000}'),i={name:"start/what-is-grok-bot.md"};function s(n,t,l,d,c,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="什么是-grok-bot" tabindex="-1">什么是 Grok Bot <a class="header-anchor" href="#什么是-grok-bot" aria-label="Permalink to &quot;什么是 Grok Bot&quot;">​</a></h1><p>如果只用一句话概括：<strong>Grok Bot 是一个能&quot;接活&quot;的 AI 同事</strong>。你像发微信一样给它发消息，它不只回一段文字，而是在自己的云端电脑上打开浏览器、跑命令、整理文件，把活干完再回来找你确认。</p><p>很多人第一次用时会下意识把它当成&quot;更聪明的聊天框&quot;，于是只问问题、不交任务。这样能用，但只用到了它很小的一部分能力。</p><h2 id="它和普通聊天-ai-有什么不同" tabindex="-1">它和普通聊天 AI 有什么不同 <a class="header-anchor" href="#它和普通聊天-ai-有什么不同" aria-label="Permalink to &quot;它和普通聊天 AI 有什么不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>普通聊天 AI</th><th>Grok Bot</th></tr></thead><tbody><tr><td>工作场所</td><td>只在对话框里</td><td>有一台持续存在的云电脑（浏览器、文件、终端）</td></tr><tr><td>关掉 App 以后</td><td>对话停住</td><td>云端的任务和例程照常进行</td></tr><tr><td>记性</td><td>多数情况下每次重新开始</td><td>每个 Bot 记得你的偏好、角色和过往工作摘要</td></tr><tr><td>能接触的工具</td><td>你复制粘贴给它的内容</td><td>通过连接器使用邮箱、代码仓库、X 等应用，也能直接操作网页</td></tr><tr><td>重复性工作</td><td>每次重新描述</td><td>可以沉淀成&quot;技能&quot;，再设成定时或事件触发的&quot;例程&quot;</td></tr><tr><td>人手</td><td>一个助手</td><td>可以建多个 Bot，各管一摊，彼此发消息分工</td></tr></tbody></table><h2 id="几个关键词-先混个脸熟" tabindex="-1">几个关键词，先混个脸熟 <a class="header-anchor" href="#几个关键词-先混个脸熟" aria-label="Permalink to &quot;几个关键词，先混个脸熟&quot;">​</a></h2><ul><li><strong>Bot</strong>：一个有名字、有职责的 AI 同事。建议&quot;一事一 Bot&quot;，比如&quot;周报助手&quot;&quot;收件箱管家&quot;。</li><li><strong>云电脑</strong>：你账号下所有 Bot 共用的一台云端 Linux 电脑，文件和登录状态会保留。每个 Bot 有自己的屏幕。</li><li><strong>记忆</strong>：Bot 会记住长期有效的偏好和规则，比如&quot;周报用表格&quot;&quot;对外邮件一律先给我看&quot;。</li><li><strong>连接器 / 插件</strong>：让 Bot 以结构化方式使用 Gmail、GitHub、Slack、X 等服务，比点网页更稳定。</li><li><strong>技能</strong>：一套可复用的做事步骤，所有 Bot 都能调用。</li><li><strong>例程</strong>：告诉某个 Bot &quot;什么时候自动做这件事&quot;，可以按时间表，也可以由事件触发。</li><li><strong>审批</strong>：发邮件、删除数据、付款这类有后果的动作，会停下来等你点头。</li></ul><div class="tip custom-block"><p class="custom-block-title">用对心态</p><p>把 Grok Bot 当成一个刚入职、很能干但还不了解你习惯的同事。第一周多交代、多纠正，它会越来越顺手。</p></div><h2 id="它适合干什么" tabindex="-1">它适合干什么 <a class="header-anchor" href="#它适合干什么" aria-label="Permalink to &quot;它适合干什么&quot;">​</a></h2><ul><li>跨好几个工具的多步骤工作：查资料 → 整理成表 → 写成草稿。</li><li>每天、每周都要做一遍的固定流程：简报、周报、数据汇总。</li><li>你不在电脑前也需要推进的事：夜里跑完、早上给你看结果。</li></ul><h2 id="它不适合什么" tabindex="-1">它不适合什么 <a class="header-anchor" href="#它不适合什么" aria-label="Permalink to &quot;它不适合什么&quot;">​</a></h2><ul><li>需要你本人身份验证的步骤（密码、验证码、支付确认），这些它会交还给你亲自操作。</li><li>没有可靠数据来源却要求&quot;给个准确数字&quot;的问题。它可以帮你找来源，但不该替你编。</li></ul><div class="warning custom-block"><p class="custom-block-title">关于套餐和用量</p><p>Grok Bot 目前仍处于持续更新阶段，可用的订阅方案、用量额度和价格会调整。本站不列具体价格，<strong>以官方最新说明为准</strong>。</p></div>',13)])])}const h=o(i,[["render",s]]);export{p as __pageData,h as default};
